/*
 * Modified by Actuna Sp. z o.o.:
 *   #84: new file - a world of fake flows for the tests of the race between a deployment, a start and the stop of
 *   the runtime: the stub of Flow.create with flows that construct and close recorded nodes, with gates on the
 *   close of a node and on the start of a flow, and the helpers of a bounded wait
 * This notice is required by section 4(b) of the Apache License 2.0.
 */

const realSetTimeout = setTimeout;
const realClearTimeout = clearTimeout;
const realSetImmediate = setImmediate;
const RealDate = Date;

/*
 * The speed of the machine must not decide about the result of a test (a slow container, coverage
 * instrumentation, a loaded host): the tests wait for events, gates and conditions, never for a
 * stretch of time. The limits below only end a test that hangs for real; they are generous and can be
 * scaled with NR_TEST_TIMEOUT_FACTOR (for example 0.1 to see quickly which tests hang against code
 * that has no fix, 3 on a very slow host).
 */
const FACTOR = Number(process.env.NR_TEST_TIMEOUT_FACTOR) > 0 ? Number(process.env.NR_TEST_TIMEOUT_FACTOR) : 1;
/** The mocha timeout of the suites of the race tests: only a safety net against a hang. */
const SUITE_TIMEOUT = Math.round(30000 * FACTOR);
/** How long a helper waits for an event or a result before it reports that it did not come. */
const WAIT_LIMIT = Math.round(20000 * FACTOR);

function deferred() {
    let resolve;
    let reject;
    const promise = new Promise(function(res, rej) { resolve = res; reject = rej });
    return { promise: promise, resolve: resolve, reject: reject };
}

async function flush(rounds) {
    for (let i = 0; i < (rounds || 3); i++) {
        await new Promise(function(resolve) { realSetImmediate(resolve) });
    }
}

/**
 * Lets everything that is chained on promises run to its end: the microtasks drain completely between two
 * turns of the event loop, so a fixed number of turns (not a stretch of time) is enough for code that has no
 * timer. Used where a test needs "nothing else happens" or "the code has reached its wait".
 */
function quiesce() {
    return flush(30);
}

/**
 * Waits until `condition()` is true (checked between the turns of the event loop). It fails with `message`
 * only after the generous WAIT_LIMIT, so a slow machine does not fail it; a condition that never comes does.
 */
async function until(condition, message, ms) {
    const limit = RealDate.now() + (ms || WAIT_LIMIT);
    while (!condition()) {
        if (RealDate.now() > limit) {
            throw new Error(message || "the condition was not reached");
        }
        await new Promise(function(resolve) { realSetImmediate(resolve) });
    }
}

/**
 * A fake clock for the code under test (the production timers and Date), for the tests whose result depends on a
 * time bound of the production code (nodeCloseTimeout, startTimeout, the timeout of the drain): the test moves the
 * clock itself, so the speed of the machine cannot change which of two events comes first. The helpers of this
 * file (settle, until, quiesce) and mocha use the real timers they captured when they were loaded.
 */
function fakeClock(sinon) {
    return sinon.useFakeTimers({
        now: RealDate.now(),
        toFake: ["setTimeout", "clearTimeout", "setInterval", "clearInterval", "Date"]
    });
}

/**
 * Follows a promise for a "has not ended yet" proof: `.done` is true once the promise settled (either way). The test
 * lets everything that can run run (quiesce) and asserts `.done` is false - no timer of the test decides the result.
 */
function watch(promise) {
    const watched = { done: false };
    Promise.resolve(promise).then(function() { watched.done = true }, function() { watched.done = true });
    return watched;
}

/**
 * Moves a fake clock past every bound of the production code (the timeout of a close, of a start, of the drain, the
 * limit of the lock: all of them are below ten minutes) and lets what is chained on the timers run. A proof that
 * something does NOT end (a stop that waits for a close in progress) is made after this, so that no production timer
 * could be what keeps it waiting for a short time only.
 */
async function pastAllBounds(clock) {
    await clock.tickAsync(10 * 60 * 1000);
    await quiesce();
}

/**
 * Waits until the code under test armed one more timer on the fake clock than `before` (`clock.countTimers()` taken
 * before the step): the wait of a stop for its bound exists, so a tick of the clock reaches it.
 */
function timerArmed(clock, before, message) {
    return until(function() { return clock.countTimers() > before }, message || "the code did not arm its timer");
}

/**
 * Waits for `promise` at most WAIT_LIMIT (a limit for a hang, not a speed requirement): never rejects and never hangs.
 * A proof that something does NOT end is not made with a short wait (that would be a stretch of time): use watch()
 * and quiesce(). Resolves
 * `{state: "resolved"|"rejected"|"timeout", value?, err?}`.
 */
function settle(promise) {
    let timer;
    const timeout = new Promise(function(resolve) {
        timer = realSetTimeout(function() { resolve({ state: "timeout" }) }, WAIT_LIMIT);
    });
    const outcome = Promise.resolve(promise).then(
        function(value) { return { state: "resolved", value: value } },
        function(err) { return { state: "rejected", err: err } }
    );
    return Promise.race([outcome, timeout]).then(function(result) {
        realClearTimeout(timer);
        return result;
    });
}

/**
 * The fake flows. `Flow.create` is replaced by a stub that makes flows with the interface the module
 * flows/index.js uses (start, stop, update, getActiveNodes, getNode). A flow constructs a recorded node for
 * every node of the active configuration that belongs to it and that it does not have, and closes the nodes
 * it is asked to close - after the gate of the node, when there is one.
 *
 *   world.created      ids of the flows made by Flow.create, in order
 *   world.starts       ids of the flows whose start was called, in order
 *   world.constructed  [{id, v, flow}] the nodes constructed (`v` of the node definition, 1 when missing)
 *   world.closeCalls   {nodeId: number of the requests to close the node}
 *   world.closed       ids of the nodes whose close completed
 *   world.stopCalls    [{flow, stopList}] every call of Flow.stop
 *   world.closeGate[id] / world.closeFail[id]   a close that waits / fails
 *   world.startGates[flowId]   the start of the flow waits; world.startHangs[flowId] = true: it never ends
 *   world.firstStartGate   a deferred: the first start that is called waits for it
 *   world.onConstruct(def)   called when a node is constructed
 *
 * `restore()` releases everything that waits and removes the stub; it is the caller's job to stop the flows
 * module afterwards (the module keeps the flow objects of a partial stop).
 */
function createWorld(Flow, sinon) {
    const world = {
        created: [],
        starts: [],
        constructed: [],
        closeCalls: {},
        closed: [],
        stopCalls: [],
        flowObjects: [],
        closeGate: {},
        closeFail: {},
        startGates: {},
        startHangs: {},
        firstStartGate: null,
        hangGate: deferred(),
        onConstruct: null
    };
    let firstStartTaken = false;

    function nodeDefs(flow) {
        const all = (flow.global && flow.global.allNodes) || {};
        return Object.keys(all).map(function(id) { return all[id] }).filter(function(def) {
            if (def.type === "tab" || def.type === "subflow") {
                return false;
            }
            return flow.isGlobal ? !def.z : def.z === flow.id;
        });
    }

    function closeNode(flow, nodeId) {
        world.closeCalls[nodeId] = (world.closeCalls[nodeId] || 0) + 1;
        const node = flow.nodes[nodeId];
        if (node.closing) {
            return node.closing;
        }
        node.closing = (async function() {
            const gate = world.closeGate[nodeId];
            if (gate) {
                await gate.promise;
            }
            delete flow.nodes[nodeId];
            world.closed.push(nodeId);
            if (world.closeFail[nodeId]) {
                throw world.closeFail[nodeId];
            }
        })();
        return node.closing;
    }

    function makeFlow(parent, global, config) {
        const isGlobal = typeof config === "undefined";
        const fake = {
            id: isGlobal ? "global" : config.id,
            isGlobal: isGlobal,
            global: global,
            nodes: {},
            fullyStopped: false,
            start: async function(diff) {
                world.starts.push(fake.id);
                if (world.firstStartGate && !firstStartTaken) {
                    firstStartTaken = true;
                    await world.firstStartGate.promise;
                }
                if (world.startHangs[fake.id]) {
                    // never ends during the test; restore() ends it so that nothing stays suspended
                    await world.hangGate.promise;
                }
                if (world.startGates[fake.id]) {
                    await world.startGates[fake.id].promise;
                }
                nodeDefs(fake).forEach(function(def) {
                    if (!fake.nodes[def.id]) {
                        world.constructed.push({ id: def.id, v: def.v || 1, flow: fake.id });
                        fake.nodes[def.id] = { id: def.id };
                        if (world.onConstruct) {
                            world.onConstruct(def);
                        }
                    }
                });
            },
            update: function(newGlobal) {
                fake.global = newGlobal;
            },
            stop: function(stopList) {
                world.stopCalls.push({ flow: fake.id, stopList: stopList ? stopList.slice() : null });
                if (!stopList) {
                    fake.fullyStopped = true;
                }
                const ids = Object.keys(fake.nodes).filter(function(id) { return !stopList || stopList.indexOf(id) !== -1 });
                return Promise.all(ids.map(function(id) { return closeNode(fake, id) }));
            },
            getActiveNodes: function() {
                return fake.nodes;
            },
            getNode: function(id) {
                return fake.nodes[id] || null;
            },
            handleError: sinon.spy(),
            handleStatus: sinon.spy()
        };
        return fake;
    }

    const stub = sinon.stub(Flow, "create").callsFake(function(parent, global, config) {
        const fake = makeFlow(parent, global, config);
        world.created.push(fake.id);
        world.flowObjects.push(fake);
        return fake;
    });

    /** The fake flows that were not stopped completely (a flow that is still "running"). */
    world.live = function() {
        return world.flowObjects.filter(function(fake) { return !fake.fullyStopped });
    };
    /** The ids of the flows that are still running (short to print in a failed assertion). */
    world.liveIds = function() {
        return world.live().map(function(fake) { return fake.id });
    };
    /** The nodes of the new configuration (v 2 and above) that were constructed. */
    world.constructedNew = function() {
        return world.constructed.filter(function(n) { return n.v >= 2 });
    };
    /** Ids of the nodes that were asked to close more than once. */
    world.closedTwice = function() {
        return Object.keys(world.closeCalls).filter(function(id) { return world.closeCalls[id] > 1 });
    };
    world.releaseAll = function() {
        Object.keys(world.closeGate).forEach(function(id) { world.closeGate[id].resolve() });
        Object.keys(world.startGates).forEach(function(id) { world.startGates[id].resolve() });
        if (world.firstStartGate) {
            world.firstStartGate.resolve();
        }
        world.hangGate.resolve();
    };
    world.restore = function() {
        world.releaseAll();
        stub.restore();
    };
    world.stub = stub;
    return world;
}

module.exports = {
    createWorld: createWorld,
    deferred: deferred,
    quiesce: quiesce,
    until: until,
    fakeClock: fakeClock,
    watch: watch,
    pastAllBounds: pastAllBounds,
    timerArmed: timerArmed,
    settle: settle,
    SUITE_TIMEOUT: SUITE_TIMEOUT,
    WAIT_LIMIT: WAIT_LIMIT
};
